"""Affine cipher implementation.

See .docs/instructions.md for the full specification.
"""

import string

ALPHABET = string.ascii_lowercase
M = len(ALPHABET)


def _modular_inverse(a, m):
    for x in range(1, m):
        if (a * x) % m == 1:
            return x
    raise ValueError("a and m must be coprime.")


def _encode_char(ch, a, b):
    index = ALPHABET.find(ch)
    return ALPHABET[(a * index + b) % M]


def _decode_char(ch, a, b):
    inverse = _modular_inverse(a, M)
    index = ALPHABET.find(ch)
    return ALPHABET[inverse * (index - b) % M]


def encode(plain_text, a, b):
    _modular_inverse(a, M)

    result = []
    for ch in plain_text.lower():
        if ch in ALPHABET:
            result.append(_encode_char(ch, a, b))
        elif ch.isdigit():
            result.append(ch)

    grouped = ["".join(result[i : i + 5]) for i in range(0, len(result), 5)]
    return " ".join(grouped)


def decode(ciphered_text, a, b):
    _modular_inverse(a, M)

    result = []
    for ch in ciphered_text.lower():
        if ch in ALPHABET:
            result.append(_decode_char(ch, a, b))
        elif ch.isdigit():
            result.append(ch)

    return "".join(result)
